import { useState, useEffect } from 'react'
import React from 'react'
import { Navbar, Nav, Container, Row, NavDropdown ,Col} from 'react-bootstrap'
import { LinkContainer } from 'react-router-bootstrap'
import { useSelector, useDispatch } from 'react-redux'
import { userLogoutAction } from '../actions/userActions'
import {NavLink, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom'


function NavigationBar( props )
{
    const userLogin = useSelector(state => state.userLogin)
    const { userInfo } = userLogin
    const dispatch = useDispatch()

    const logoutHandler = () => {
        dispatch(userLogoutAction())
        window.location.reload();


    }
    const [anchorEl, setAnchorEl] = React.useState(null);
    const open = Boolean(anchorEl);
    const handleClick = (event) => {
      setAnchorEl(event.currentTarget);
    };
    const handleClose = () => {
      setAnchorEl(null);
    };

    return (
        <Navbar bg="dark" variant="light" data-bs-theme="dark" style={{ direction:'rtl',height:"60px",}}>
            <Container fluid>
                <Nav className="ml-auto"> 
                    <LinkContainer to="/" style={{marginLeft:'50px'}}>
                        <Navbar.Brand className="nav-item">
                        <h1 className='py-2'>سیستم مدیریت کنترل قبوض برق آلپاسافت</h1>
                        </Navbar.Brand>
                    </LinkContainer>

                        <LinkContainer to="/companies">
                            <NavLink className='navlink'>مشترکین</NavLink>
                        </LinkContainer>
                        <NavDropdown
                        title={<span className='navlink'>بارگذاری قبوض</span>}

                        >
                        <NavDropdown.Item >
                            <NavLink  className='navitem'>قبض برق</NavLink>
                        </NavDropdown.Item>
                        <NavDropdown.Item>
                            <NavLink className='navitem'>قبض آب</NavLink>
                        </NavDropdown.Item>
                        </NavDropdown>

                </Nav>

                <Nav className="ms-auto">
                    { userInfo && 
                    <> 
                    <NavDropdown
                        title={userInfo.username}
                        menuVariant="dark"
                    >
                        <NavDropdown.Item>
                            <NavLink >Logout</NavLink>
                        </NavDropdown.Item>
                    </NavDropdown>
                    </>
                    }

                    { !userInfo &&
                    <LinkContainer to="/login">
                        <NavLink>Login</NavLink>
                    </LinkContainer>
                    }
                </Nav>
            </Container>
        </Navbar>
    )

}

export default NavigationBar;
